"use strict";function t(t){if(!t)return null;const e=t.includes("T")?t:t.replace(" ","T"),i=new Date(e);return Number.isNaN(i.getTime())?null:i}exports.formatBeijingDate=function(e){const i=t(e);return i?new Intl.DateTimeFormat("zh-CN",{timeZone:"Asia/Shanghai",year:"numeric",month:"2-digit",day:"2-digit"}).format(i).replace(/\//g,"-"):""},exports.formatBeijingDateTime=function(e){const i=t(e);return i?new Intl.DateTimeFormat("zh-CN",{timeZone:"Asia/Shanghai",year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",hour12:!1}).format(i).replace(/\//g,"-"):""},exports.formatBeijingTime=function(e){const i=t(e);return i?new Intl.DateTimeFormat("zh-CN",{timeZone:"Asia/Shanghai",hour:"2-digit",minute:"2-digit",hour12:!1}).format(i):""},exports.formatDate=function(t){return`${t.getFullYear()}-${String(t.getMonth()+1).padStart(2,"0")}-${String(t.getDate()).padStart(2,"0")}`};
